import pathlib,base64,subprocess,json,os
root=pathlib.Path('/content/mathvisionkid_t4_budget_3h_20261023')
script=root/'posthoc_bind_benchmarks.py'
script.write_bytes(base64.b64decode(''))
log=(root/'benchmark_id_binding.log').open('ab')
env=dict(os.environ);env['CUDA_VISIBLE_DEVICES']='';env['HF_HUB_OFFLINE']='1';env['TRANSFORMERS_OFFLINE']='1'
cmd=[str(root/'venv/bin/python'),str(script),'--train-view',str(root/'sampling/run/training_view.jsonl'),'--manifest',str(root/'sampling/run/training_view_manifest.json'),'--native-report',str(root/'torch_baseline_benchmark.json'),'--unsloth-report',str(root/'training/run_config.json'),'--output',str(root/'benchmark_id_binding.json')]
assert not globals().get('benchmark_binding_process') or benchmark_binding_process.poll() is not None
benchmark_binding_process=subprocess.Popen(cmd,stdout=log,stderr=subprocess.STDOUT,env=env)
print(json.dumps({'cpu_only':True,'pid':benchmark_binding_process.pid,'gpu_training_unchanged':True}))
